package com.tarapickle.identity.domain.model; import jakarta.persistence.*; import lombok.*; import java.time.*; import java.util.*;
@Entity @Table(name="security_events") @NoArgsConstructor(access=AccessLevel.PROTECTED) public class SecurityEvent { @Id private UUID id; @Column(name="user_id") private UUID userId; @Column(name="session_id") private UUID sessionId; @Column(name="event_type") private String eventType; private String outcome; @Column(name="occurred_at") private Instant occurredAt; @Column(name="ip_address") private String ip; private String metadata; public SecurityEvent(UUID uid,UUID sid,String type,String outcome,Instant at,String ip){id=UUID.randomUUID();userId=uid;sessionId=sid;eventType=type;this.outcome=outcome;occurredAt=at;this.ip=ip;} }
